function getC4Concept(id) {
	return c4Concepts.find((concept) => concept.id === id) ?? null;
}
function c4Copy(concept, lang) {
	if (lang !== "en") return {
		title: concept.title,
		why: concept.why,
		prior: concept.prior,
		see: concept.see,
		plain: concept.plain,
		situation: concept.situation,
		use: concept.use,
		precise: concept.precise,
		insight: concept.insight,
		formula: concept.formula,
		symbols: concept.symbols
	};
	const en = c4En[concept.id];
	if (!en) return c4Copy(concept, "vi");
	return {
		title: en.title,
		why: en.why,
		prior: en.prior,
		see: en.see,
		plain: en.plain,
		situation: en.situation,
		use: en.use,
		precise: en.precise,
		insight: en.insight,
		formula: concept.formula,
		symbols: concept.symbols.map((row, index) => ({
			sym: row.sym,
			meaning: en.symbols[index] ?? row.meaning
		}))
	};
}
