function brow(module) {
	if (module === "Hypothesis Testing") return "C2 · Hypothesis Testing";
	if (module === "Exploratory Data Analysis") return "C2 · EDA";
	return "C2 · SQL";
}
var restConcepts = restSessions.flatMap((session) => session.concepts.map((concept) => ({
	...concept,
	eyebrow: brow(concept.module)
})));
function getRestConcept(id) {
	return restConcepts.find((concept) => concept.id === id) ?? null;
}
function restCopy(concept, lang) {
	if (lang !== "en") return {
		title: concept.title,
		why: concept.why,
		prior: concept.prior,
		see: concept.see,
		plain: concept.plain,
		situation: concept.situation,
		use: concept.use,
		precise: concept.precise,
		insight: concept.insight,
		formula: concept.formula,
		symbols: concept.symbols
	};
	const en = restEn[concept.id];
	if (!en) return restCopy(concept, "vi");
	return {
		title: en.title,
		why: en.why,
		prior: en.prior,
		see: en.see,
		plain: en.plain,
		situation: en.situation,
		use: en.use,
		precise: en.precise,
		insight: en.insight,
		formula: concept.formula,
		symbols: concept.symbols.map((row, index) => ({
			sym: row.sym,
			meaning: en.symbols[index] ?? row.meaning
		}))
	};
}
